function redactText(v){return String(v).slice(0,4000).replace(/https?:\/\/[^\s<>"']+/g,x=>{try{const u=new URL(x);u.username='';u.password='';u.search='';u.hash='';return u.href;}catch{return '[redacted-url]';}}).replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,'[redacted-email]').replace(/\b(password|token|secret|authorization|cookie)\s*[:=]\s*[^\s,;]+/gi,'$1=[redacted]');}
