 const runPublic=r=>{if(!r)return r;const job=db.prepare('SELECT created_at,due_at FROM jobs WHERE id=?').get(r.job_id);const review=r.proposal_id?db.prepare('SELECT status,reviewed_at FROM proposals WHERE id=?').get(r.proposal_id):null;const displayStatus=r.status==='awaiting_semantic_review'&&['approved','rejected'].includes(review?.status)?'review_'+review.status:r.status;return ({id:r.id,runId:r.id,jobId:r.job_id,siteId:r.site_id,profileRevision:r.profile_revision,siteRevision:r.site_revision,config:parse(r.config_json),configHash:r.config_hash,executionMode:r.execution_mode,purpose:r.purpose,...(r.collection_scope==='public_references'?{collectionScope:r.collection_scope}:{}),status:displayStatus,collectionStatus:r.status,reviewStatus:review?.status??null,reviewedAt:iso(review?.reviewed_at),createdAt:iso(job?.created_at),enqueuedAt:iso(job?.created_at),dueAt:iso(job?.due_at),startedAt:iso(r.started_at),finishedAt:iso(r.finished_at),outcome:parse(r.outcome_json),capabilities:parse(r.capabilities_json),evidenceIds:parse(r.evidence_ids_json)||[],proposalId:r.proposal_id,blocker:parse(r.blocker_json),parentCheckpointId:r.parent_checkpoint_id});};
