 function initializeProfiles(configs){if(!Array.isArray(configs))throw Error('Config array required');return tx(()=>{let created=0;for(const input of configs){const id=input.recordId||input.id;if(!id||profileRow(id)||!store.getSite(id))continue;const c=cleanConfig(input,{siteId:id,legacy:true});db.prepare('INSERT INTO collector_profiles(site_id,config_json,revision) VALUES(?,?,1)').run(id,JSON.stringify(c));if(c.publicReferenceEnabled===true)db.prepare('INSERT OR IGNORE INTO performance_reference_schedule(site_id,due_at) VALUES(?,?)').run(id,clock()+c.refreshIntervalMs);created++;}return {created,total:db.prepare('SELECT COUNT(*) n FROM collector_profiles').get().n};});}
